package info.u_team.music_player.init;

import static net.fabricmc.fabric.api.client.command.v2.ClientCommandManager.argument;
import static net.fabricmc.fabric.api.client.command.v2.ClientCommandManager.literal;
import com.mojang.brigadier.arguments.StringArgumentType;
import info.u_team.music_player.gui.GuiMusicPlayer;import info.u_team.music_player.musicplayer.MusicPlayerManager;import info.u_team.music_player.musicplayer.MusicPlayerUtils;import info.u_team.music_player.musicplayer.PlaybackActions;import info.u_team.music_player.musicplayer.TrackRadioService;import net.fabricmc.fabric.api.client.command.v2.ClientCommandRegistrationCallback;import net.minecraft.client.Minecraft;
public final class MusicPlayerClientCommands{private MusicPlayerClientCommands(){}public static void register(){ClientCommandRegistrationCallback.EVENT.register((dispatcher,access)->dispatcher.register(literal("music").then(literal("open").executes(c->{Minecraft.getInstance().setScreen(new GuiMusicPlayer());return 1;})).then(literal("play").executes(c->{final var m=MusicPlayerManager.getPlayer().getTrackManager();if(m.getCurrentTrack()!=null)m.setPaused(false);return 1;})).then(literal("pause").executes(c->{final var m=MusicPlayerManager.getPlayer().getTrackManager();if(m.getCurrentTrack()!=null)m.setPaused(true);return 1;})).then(literal("next").executes(c->{MusicPlayerUtils.skipForward();return 1;})).then(literal("previous").executes(c->{MusicPlayerUtils.skipBack();return 1;})).then(literal("stop").executes(c->{MusicPlayerManager.getPlayer().getTrackManager().stop();return 1;})).then(literal("radio").executes(c->{TrackRadioService.queueRecommendations(10,v->{});return 1;})).then(literal("load").then(argument("uri",StringArgumentType.greedyString()).executes(c->{PlaybackActions.playNow(StringArgumentType.getString(c,"uri"),v->{});return 1;}))).then(literal("queue").then(argument("uri",StringArgumentType.greedyString()).executes(c->{PlaybackActions.queue(StringArgumentType.getString(c,"uri"),v->{});return 1;})))));}}
